SELECT

FROM inc_department
WHERE delete_state = 0
  AND institute_id = #{instituteId,jdbcType=VARCHAR}
  AND third_id = #{thirdId,jdbcType=VARCHAR}


SELECT

FROM inc_department
WHERE delete_state = 0
  AND institute_id = #{instituteId,jdbcType=VARCHAR}
  AND dept_code = #{deptCode,jdbcType=VARCHAR}


SELECT

FROM inc_department
WHERE delete_state = 0
  AND institute_id = #{instituteId,jdbcType=VARCHAR}
  AND parent_id = #{parentId,jdbcType=VARCHAR}
  AND dept_name = #{deptName,jdbcType=VARCHAR}


SELECT dept.id, dept.parent_id, dept.institute_id, dept.area_id, area.area_name,
  dept.dept_name, dept.dept_code, dept.address, dept.description, dept.is_default, dept.third_id
FROM inc_department dept
LEFT JOIN inc_area area ON area.id = dept.area_id
WHERE dept.delete_state = 0

  AND dept.institute_id = #{instituteId,jdbcType=VARCHAR}


  AND dept.parent_id = #{parentId,jdbcType=VARCHAR}


  AND dept.area_id = #{areaId,jdbcType=VARCHAR}
